/* V4 early (runs right after the title screen is built): Pix's title art (logo + six heroes) as the title screen picture at once,
   and the login/start area hidden until the rest of the game has loaded (no old-version flash) */
(function(){try{
const ART='data:image/webp;base64,';window.__SPART=ART;
const st=document.createElement('style');st.id='v4_early_css';st.textContent=
 'html body #splash.nw{background:url('+ART+') 50% 12px/92.6% auto no-repeat,linear-gradient(#3fa4ff 0,#3fa4ff 30%,#7fa06a 60%,#4f6b45 100%)!important}'+
 '@media (orientation:landscape){html body #splash.nw{background:url('+ART+') 50% 10px/auto calc(100% - 150px) no-repeat,linear-gradient(#3fa4ff 0,#3fa4ff 45%,#7fa06a 75%,#4f6b45 100%)!important}}'+
 'html body #splash.nw .xl,html body #splash.nw .xs{display:none!important}'+
 'html body #splash.nw .spB{margin-top:auto!important}'+
 '#splash:not(.v4r) .xau,#splash:not(.v4r) .xsoon,#splash:not(.v4r) #bgn{visibility:hidden!important}';
document.head.appendChild(st);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();window.__bip=e});
}catch(e){console.log('v4 early',e)}})();
